import java.util.ArrayList;
import java.util.List;

public class Repack {
    public static void main(String[] args) throws Exception {
        File jar = new File(args[0]);
        String cp = Files.readString(Path.of(args[1]));
        List<File> libs = new ArrayList<>();
        for (String entry : cp.split(":")) {
            if (entry.isBlank()) continue;
            File f = new File(entry.trim());
            if (f.getName().startsWith("lombok")) continue;
            if (!f.isFile()) { System.err.println("missing lib: " + f); continue; }
            libs.add(f);
        }
        Repackager repackager = new Repackager(jar);
        repackager.repackage(jar, callback -> {
            for (File f : libs) {
                callback.library(f, LibraryScope.RUNTIME);
            }
        });
        System.out.println("Repackaged " + jar + " with " + libs.size() + " libraries");
    }
}
